# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#1e293b">TÜRKİYE\'NİN İŞLEVSEL BÖLGELERİ (YÖNETSEL, HİZMET VE İSTATİSTİKİ)</text>\n\n  <!-- Kart 1: İşlevsel Yönetsel Bölgeler -->\n  <rect x="16" y="45" width="214" height="198" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="123" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">1. YÖNETSEL BÖLGELER</text>\n  <line x1="28" y1="76" x2="218" y2="76" stroke="#93c5fd" stroke-width="1.5"/>\n  <text x="28" y="96" font-size="10" fill="#1e3a8a">• İl, ilçe ve köy sınırlarına göre</text>\n  <text x="34" y="110" font-size="10" fill="#1e3a8a">merkezî ve yerel yönetimlerdir.</text>\n  <rect x="28" y="122" width="190" height="82" rx="6" fill="#dbeafe" stroke="#3b82f6"/>\n  <text x="123" y="140" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">Yıllara Göre İl Sayısı:</text>\n  <text x="42" y="158" font-size="10" font-weight="bold" fill="#1e3a8a">• 1923: 55 il   • 1950: 62 il</text>\n  <text x="42" y="176" font-size="10" font-weight="bold" fill="#1e3a8a">• 1980: 67 il   • Günümüz: 81 il</text>\n  <text x="123" y="196" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">(30 Büyükşehir Belediyesi)</text>\n  <text x="123" y="226" text-anchor="middle" font-size="9.5" fill="#334155">Valilik, Kaymakamlık, Belediye</text>\n\n  <!-- Kart 2: İşlevsel Hizmet Bölgeleri -->\n  <rect x="243" y="45" width="214" height="198" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. HİZMET BÖLGELERİ</text>\n  <line x1="255" y1="76" x2="445" y2="76" stroke="#86efac" stroke-width="1.5"/>\n  <text x="255" y="96" font-size="10" fill="#14532d">• Kamu hizmetlerinin etkin dağıtımı</text>\n  <text x="261" y="110" font-size="10" fill="#14532d">için kurulan bölge müdürlükleri:</text>\n  <rect x="255" y="122" width="190" height="96" rx="6" fill="#dcfce7" stroke="#22c55e"/>\n  <text x="265" y="142" font-size="10" font-weight="bold" fill="#14532d">• Karayolları Gn. Md.: 18 bölge</text>\n  <text x="265" y="162" font-size="10" font-weight="bold" fill="#14532d">• Devlet Su İşleri (DSİ): 26 bölge</text>\n  <text x="265" y="182" font-size="10" font-weight="bold" fill="#14532d">• Meteoroloji Gn. Md.: 16 bölge</text>\n  <text x="265" y="202" font-size="10" font-weight="bold" fill="#14532d">• Doğa Koruma ve MP: 15 bölge</text>\n  <text x="350" y="232" text-anchor="middle" font-size="9.5" fill="#166534">İl sınırlarıyla çakışmak zorunda değildir.</text>\n\n  <!-- Kart 3: İşlevsel İstatistiki Bölgeler -->\n  <rect x="470" y="45" width="214" height="198" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="577" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">3. İSTATİSTİKİ BÖLGELER</text>\n  <line x1="482" y1="76" x2="672" y2="76" stroke="#fde047" stroke-width="1.5"/>\n  <text x="482" y="96" font-size="10" fill="#713f12">• TÜİK tarafından AB İstatistiki</text>\n  <text x="488" y="110" font-size="10" fill="#713f12">Bölge Birimleri Sınıflandırması\'na</text>\n  <text x="488" y="124" font-size="10" fill="#713f12">(İBBS) uyumlu oluşturulmuştur:</text>\n  <rect x="484" y="136" width="186" height="82" rx="6" fill="#fef08a" stroke="#eab308"/>\n  <text x="496" y="158" font-size="10.5" font-weight="bold" fill="#713f12">• Düzey 1: 12 Bölge</text>\n  <text x="496" y="180" font-size="10.5" font-weight="bold" fill="#713f12">• Düzey 2: 26 Alt Bölge</text>\n  <text x="496" y="202" font-size="10.5" font-weight="bold" fill="#713f12">• Düzey 3: 81 İl</text>\n  <text x="577" y="232" text-anchor="middle" font-size="9.5" fill="#854d0e">Sosyoekonomik analiz ve planlama</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#1e293b">TÜRKİYE\'NİN BÖLGESEL KALKINMA PROJELERİ (İŞLEVSEL PLAN BÖLGELERİ)</text>\n\n  <!-- 6 Proje Kartı (2x3 Grid) -->\n  <rect x="16" y="42" width="214" height="96" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="123" y="60" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1d4ed8">1. GAP (Güneydoğu Anadolu)</text>\n  <text x="26" y="78" font-size="9.5" fill="#1e3a8a">• 9 il | Fırat ve Dicle: 22 baraj, 19 HES</text>\n  <text x="26" y="94" font-size="9.5" fill="#1e3a8a">• Sulamayla pamuk ve mısır üretiminde</text>\n  <text x="26" y="108" font-size="9.5" font-weight="bold" fill="#1e40af">  Türkiye birinciliği sağlandı.</text>\n  <text x="26" y="124" font-size="9" fill="#334155">• Tarıma dayalı sanayi gelişti.</text>\n\n  <rect x="243" y="42" width="214" height="96" rx="8" fill="#fefce8" stroke="#ca8a04" stroke-width="1.8"/>\n  <text x="350" y="60" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#a16207">2. DAP (Doğu Anadolu)</text>\n  <text x="253" y="78" font-size="9.5" fill="#713f12">• 15 il (En fazla il kapsayan proje)</text>\n  <text x="253" y="94" font-size="9.5" fill="#713f12">• Mera ıslahı ve büyükbaş hayvancılığın</text>\n  <text x="253" y="108" font-size="9.5" font-weight="bold" fill="#854d0e">  geliştirilmesi temel hedeftir.</text>\n  <text x="253" y="124" font-size="9" fill="#713f12">• Kış turizmi ve madencilik desteği.</text>\n\n  <rect x="470" y="42" width="214" height="96" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="577" y="60" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">3. DOKAP (Doğu Karadeniz)</text>\n  <text x="480" y="78" font-size="9.5" fill="#14532d">• Yayla turizmi ve Yeşil Yol projesi</text>\n  <text x="480" y="94" font-size="9.5" fill="#14532d">• Çay ve fındık tarımında verim artışı</text>\n  <text x="480" y="108" font-size="9.5" font-weight="bold" fill="#166534">• Kıyı ve iç kesim ulaşımının</text>\n  <text x="480" y="124" font-size="9" fill="#14532d">  güçlendirilmesi hedeflenir.</text>\n\n  <rect x="16" y="148" width="214" height="96" rx="8" fill="#fff7ed" stroke="#ea580c" stroke-width="1.8"/>\n  <text x="123" y="166" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#c2410c">4. KOP (Konya Ovası Projesi)</text>\n  <text x="26" y="184" font-size="9.5" fill="#7c2d12">• 8 il | Mavi Tünel ile Göksu Nehri</text>\n  <text x="26" y="200" font-size="9.5" fill="#7c2d12">  sularının Konya Ovası\'na aktarılması</text>\n  <text x="26" y="214" font-size="9.5" font-weight="bold" fill="#9a3412">• Yer altı sularının korunması ve</text>\n  <text x="26" y="230" font-size="9" fill="#7c2d12">  obruk oluşumunun önlenmesi.</text>\n\n  <rect x="243" y="148" width="214" height="96" rx="8" fill="#f1f5f9" stroke="#475569" stroke-width="1.8"/>\n  <text x="350" y="166" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">5. ZBK (Zonguldak-Bartın-Karabük)</text>\n  <text x="253" y="184" font-size="9.5" fill="#334155">• 3 il | Taş kömürü madenciliği ve</text>\n  <text x="253" y="200" font-size="9.5" fill="#334155">  demir-çelik sanayisinin modernizasyonu</text>\n  <text x="253" y="214" font-size="9.5" font-weight="bold" fill="#0f172a">• Filyos Limanı ve Filyos Vadisi</text>\n  <text x="253" y="230" font-size="9" fill="#334155">  endüstri bölgesi yatırımları.</text>\n\n  <rect x="470" y="148" width="214" height="96" rx="8" fill="#ecfdf5" stroke="#0d9488" stroke-width="1.8"/>\n  <text x="577" y="166" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#0f766e">6. YHGP (Yeşilırmak Havzası)</text>\n  <text x="480" y="184" font-size="9.5" fill="#134e4a">• 4 il: Amasya, Çorum, Samsun, Tokat</text>\n  <text x="480" y="200" font-size="9.5" fill="#134e4a">• Yeşilırmak\'ta akarsu kirliliği, erozyon</text>\n  <text x="480" y="214" font-size="9.5" font-weight="bold" fill="#115e59">  ve taşkın kontrolü sağlama.</text>\n  <text x="480" y="230" font-size="9" fill="#134e4a">• Havza ekolojisini koruma.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#1e293b">TÜRKİYE\'DE ULAŞIMI ETKİLEYEN DOĞAL VE BEŞERÎ FAKTÖRLER</text>\n\n  <!-- Sol Kutu: Doğal Faktörler -->\n  <rect x="18" y="45" width="340" height="198" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="188" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">DOĞAL FAKTÖRLER</text>\n  <line x1="32" y1="76" x2="344" y2="76" stroke="#93c5fd" stroke-width="1.5"/>\n  <text x="30" y="96" font-size="10.5" font-weight="bold" fill="#1e3a8a">1) Coğrafi Konum:</text>\n  <text x="38" y="110" font-size="9.8" fill="#1e40af">Asya-Avrupa-Afrika kesişimi, İstanbul ve Çanakkale boğazları.</text>\n  <text x="30" y="130" font-size="10.5" font-weight="bold" fill="#1e3a8a">2) Yeryüzü Şekilleri (Doğu-Batı Uzantılı Dağlar):</text>\n  <text x="38" y="145" font-size="9.5" fill="#1e40af">• Kuzey-güney ulaşımı geçit ve tünellerle sağlanır:</text>\n  <text x="44" y="160" font-size="9.5" font-weight="bold" fill="#1d4ed8">Geçitler: Gülek, Sertavul, Çubuk, Zigana, Kop</text>\n  <text x="44" y="175" font-size="9.5" font-weight="bold" fill="#b91c1c">Ovit Tüneli (14 km çift tüplü): Rize İkizdere - Erzurum İspir</text>\n  <text x="38" y="191" font-size="9.5" fill="#1e40af">• Sinop: Küre Dağları nedeniyle hinterlandı dar kalmıştır.</text>\n  <text x="30" y="212" font-size="10.5" font-weight="bold" fill="#1e3a8a">3) İklim Koşulları:</text>\n  <text x="38" y="226" font-size="9.8" fill="#1e40af">Yoğun kar yağışı, buzlanma, don, sis ve fırtına.</text>\n\n  <!-- Sağ Kutu: Beşerî Faktörler -->\n  <rect x="372" y="45" width="310" height="198" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="527" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">BEŞERÎ VE EKONOMİK FAKTÖRLER</text>\n  <line x1="386" y1="76" x2="668" y2="76" stroke="#86efac" stroke-width="1.5"/>\n  <text x="386" y="98" font-size="10.5" font-weight="bold" fill="#14532d">1) Nüfus ve Yerleşme Yoğunluğu</text>\n  <text x="386" y="120" font-size="10.5" font-weight="bold" fill="#14532d">2) Ekonomik Faaliyetler:</text>\n  <text x="394" y="136" font-size="10" fill="#166534">Sanayi, ticaret, tarım, madencilik ve turizm</text>\n  <text x="386" y="158" font-size="10.5" font-weight="bold" fill="#14532d">3) Sermaye ve Teknolojik Gelişmeler:</text>\n  <rect x="386" y="168" width="282" height="62" rx="6" fill="#dcfce7" stroke="#22c55e"/>\n  <text x="527" y="186" text-anchor="middle" font-size="10" font-weight="bold" fill="#14532d">Modern Ulaşım Projeleri:</text>\n  <text x="527" y="203" text-anchor="middle" font-size="9.5" fill="#166534">Marmaray, Avrasya Tüneli, Osmangazi ve</text>\n  <text x="527" y="219" text-anchor="middle" font-size="9.5" fill="#166534">Yavuz Sultan Selim Köprüleri, YHT Hatları</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
